begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,is_anonymous) values ('c0000000-0000-4000-8000-000000000001',true),('c0000000-0000-4000-8000-000000000002',true);
set local request.jwt.claims = '{"sub":"c0000000-0000-4000-8000-000000000001","is_anonymous":true}';
set local role authenticated;
select is(public.sg_cloud_save('list',null,'{}')->'slots','[]'::jsonb,'empty list');
select throws_ok($$select public.sg_cloud_save('load','profile','{}')$$,'P0002','SAVE_NOT_FOUND','missing slot');
select is(public.sg_cloud_save('save','profile','{"expectedRevision":0,"operationId":"d0000000-0000-4000-8000-000000000001","schemaVersion":1,"data":{"coins":5},"metadata":{}}')->'save'->>'revision','1','first save');
select is(public.sg_cloud_save('save','profile','{"expectedRevision":0,"operationId":"d0000000-0000-4000-8000-000000000001","schemaVersion":1,"data":{"coins":5},"metadata":{}}')->'save'->>'revision','1','identical retry returns original receipt');
select throws_ok($$select public.sg_cloud_save('save','profile','{"expectedRevision":0,"operationId":"d0000000-0000-4000-8000-000000000001","schemaVersion":1,"data":{"coins":6},"metadata":{}}')$$,'23505','DUPLICATE_KEY_CONFLICT','key cannot change payload');
select is(public.sg_cloud_save('save','profile','{"expectedRevision":0,"operationId":"d0000000-0000-4000-8000-000000000002","schemaVersion":1,"data":{},"metadata":{}}')->>'code','SAVE_CONFLICT','stale create conflicts');
select is(public.sg_cloud_save('save','profile','{"expectedRevision":0,"operationId":"d0000000-0000-4000-8000-000000000002","schemaVersion":1,"data":{},"metadata":{}}')->'current'->>'revision','1','conflict supplies latest metadata and data');
select is(public.sg_cloud_save('save','profile','{"expectedRevision":1,"operationId":"d0000000-0000-4000-8000-000000000003","schemaVersion":2,"data":[1,true,null],"metadata":{"label":"A"}}')->'save'->>'revision','2','update increments revision with arbitrary JSON');
select is(public.sg_cloud_save('load','profile','{}')->'save'->>'schemaVersion','2','schema version round trip');
select is(jsonb_array_length(public.sg_cloud_save('list',null,'{}')->'slots'),1,'lists metadata');
select throws_ok($$select public.sg_cloud_save('save','../bad','{}')$$,'22023','INVALID_SAVE','unsafe slot');
select throws_ok($$select public.sg_cloud_save('save','x','{"expectedRevision":0,"operationId":"d0000000-0000-4000-8000-000000000005","schemaVersion":-1,"data":null,"metadata":{}}')$$,'22023','INVALID_SAVE','invalid schema');
select throws_ok($$select public.sg_cloud_save('save','x','{"ownerId":"c0000000-0000-4000-8000-000000000002"}')$$,'22023','INVALID_SAVE','forged owner rejected');
select throws_ok($$insert into public.game_saves(user_id,slot) values(auth.uid(),'forged')$$,'42501',null,'direct insert denied');
select throws_ok($$update public.game_saves set revision=999$$,'42501',null,'direct revision edit denied');
set local request.jwt.claims = '{"sub":"c0000000-0000-4000-8000-000000000002"}';
select is((select count(*) from public.game_saves),0::bigint,'RLS isolates players');
select throws_ok($$select public.sg_cloud_save('load','profile','{}')$$,'P0002','SAVE_NOT_FOUND','cannot load another player');
select is(public.sg_cloud_save('delete','profile','{"expectedRevision":2,"operationId":"d0000000-0000-4000-8000-000000000006"}')->>'code','SAVE_CONFLICT','cannot delete another player');
set local request.jwt.claims = '{"sub":"c0000000-0000-4000-8000-000000000001"}';
select is(public.sg_cloud_save('delete','profile','{"expectedRevision":2,"operationId":"d0000000-0000-4000-8000-000000000007"}')->'save'->>'revision','3','delete creates revisioned tombstone');
select throws_ok($$select public.sg_cloud_save('load','profile','{}')$$,'P0002','SAVE_NOT_FOUND','deleted load is missing');
select is(public.sg_cloud_save('save','profile','{"expectedRevision":0,"operationId":"d0000000-0000-4000-8000-000000000008","schemaVersion":1,"data":{},"metadata":{}}')->'current'->>'revision','3','tombstone prevents stale resurrection');
reset role;
update sg_private.save_config set max_slots=1,max_json_bytes=30;
set local role authenticated;
select throws_ok($$select public.sg_cloud_save('save','big',jsonb_build_object('expectedRevision',0,'operationId',gen_random_uuid(),'schemaVersion',1,'data',repeat('x',31),'metadata','{}'::jsonb))$$,'54000','SAVE_QUOTA_EXCEEDED','size enforced');
select public.sg_cloud_save('save','one',jsonb_build_object('expectedRevision',0,'operationId',gen_random_uuid(),'schemaVersion',1,'data',null,'metadata','{}'::jsonb));
select throws_ok($$select public.sg_cloud_save('save','two',jsonb_build_object('expectedRevision',0,'operationId',gen_random_uuid(),'schemaVersion',1,'data',null,'metadata','{}'::jsonb))$$,'54000','SAVE_QUOTA_EXCEEDED','slot quota enforced');
reset role;
set local role anon;
select throws_ok($$select public.sg_cloud_save('list',null,'{}')$$,'42501',null,'unauthenticated denied');
reset role;
select * from finish();
rollback;
